  35: struct PasswordGenerator {
  36:     charset: Vec<u8>,
  37:     // Direct lookup table: byte value -> index in charset (avoids HashMap hashing)
  38:     charset_lookup: [u8; 128],
  39:     charset_len: usize,
  40:     charset_last_idx: u8,
  41:     max_size: usize,
  42:     generated_count: usize,
  43:     total_to_generate: usize,
  44:     password: Vec<u8>,
  45:     progress_bar: ProgressBar,
  46: }
  47: 
  48: impl PasswordGenerator {
  49:     fn new(
  50:         charset: Vec<char>,
  51:         min_size: usize,
  52:         max_size: usize,
  53:         starting_password: Option<String>,
  54:         progress_bar: ProgressBar,
  55:     ) -> Self {
  56:         let charset_bytes: Vec<u8> = charset.iter().map(|&c| c as u8).collect();
  57:         let charset_len = charset_bytes.len();
  58: 
  59:         // Build direct lookup table: byte -> index in charset
  60:         let mut charset_lookup = [0u8; 128];
  61:         for (i, &b) in charset_bytes.iter().enumerate() {
  62:             charset_lookup[b as usize] = i as u8;
  63:         }
  64: 
  65:         let charset_last_idx = (charset_len - 1) as u8;
  66: 
  67:         let mut password = vec![charset_bytes[0]; min_size];
  68:         let mut total_to_generate = password_generator_count(charset_len, min_size, max_size);
  69:         if let Some(starting_password) = starting_password {
  70:             password = starting_password.bytes().collect();
  71:             let password_len = password.len();
  72:             let already_generated_count =
  73:                 password_count_already_generated(&charset, min_size, &starting_password);
  74:             // decrease number of password to generate
  75:             total_to_generate -= already_generated_count;
  76:             progress_bar.println(format!(
  77:                 "Starting search space for password length {password_len} from {starting_password} (skipping {already_generated_count} passwords)"
  78:             ));
  79:         } else {
  80:             // possible passwords at min size
  81:             let possibilities = charset_len.pow(min_size as u32);
  82:             progress_bar.println(format!(
  83:                 "Starting search space for password length {min_size} ({possibilities} possibilities)"
  84:             ));
  85:         }
  86: 
  87:         Self {
  88:             charset: charset_bytes,
  89:             charset_lookup,
  90:             charset_len,
  91:             charset_last_idx,
  92:             max_size,
  93:             generated_count: 0,
  94:             total_to_generate,
  95:             password,
  96:             progress_bar,
  97:         }
  98:     }
  99: }
