 101: impl Iterator for PasswordGenerator {
 102:     type Item = Vec<u8>;
 103: 
 104:     fn next(&mut self) -> Option<Self::Item> {
 105:         if self.password.len() > self.max_size {
 106:             return None;
 107:         }
 108: 
 109:         // first password
 110:         if self.generated_count == 0 {
 111:             self.generated_count += 1;
 112:             return Some(self.password.clone());
 113:         }
 114: 
 115:         // end of search space
 116:         if self.generated_count == self.total_to_generate {
 117:             return None;
 118:         }
 119: 
 120:         // Odometer-style increment from rightmost position
 121:         let mut carry = true;
 122:         for i in (0..self.password.len()).rev() {
 123:             if !carry {
 124:                 break;
 125:             }
 126:             let idx = self.charset_lookup[self.password[i] as usize];
 127:             if idx < self.charset_last_idx {
 128:                 self.password[i] = self.charset[(idx + 1) as usize];
 129:                 carry = false;
 130:             } else {
 131:                 self.password[i] = self.charset[0];
 132:             }
 133:         }
 134: 
 135:         if carry {
 136:             // All positions overflowed -> increase length
 137:             let new_len = self.password.len() + 1;
 138:             self.password = vec![self.charset[0]; new_len];
 139:             let possibilities = self.charset_len.pow(new_len as u32);
 140:             self.progress_bar.println(format!(
 141:                 "Starting search space for password length {} ({} possibilities) ({} passwords generated so far)",
 142:                 new_len, possibilities, self.generated_count
 143:             ));
 144:         }
 145: 
 146:         self.generated_count += 1;
 147:         Some(self.password.clone())
 148:     }
 149: 
 150:     fn size_hint(&self) -> (usize, Option<usize>) {
 151:         let remaining = self.total_to_generate - self.generated_count;
 152:         (remaining, Some(remaining))
 153:     }
 154: }
